using Aspire.Hosting.Testing;
using Microsoft.Extensions.AI;
using Microsoft.Extensions.AI.Evaluation;
using Microsoft.Extensions.AI.Evaluation.Quality;
using Microsoft.Extensions.AI.Evaluation.Reporting;
using Microsoft.Extensions.DependencyInjection;

namespace MyApp.Evaluations;

[TestClass]
public class ChatEvaluationTests
{
    private static DistributedApplicationTestingBuilder _appHost = null!;
    private static DistributedApplication _app = null!;

    [ClassInitialize]
    public static async Task ClassInitialize(TestContext context)
    {
        _appHost = await DistributedApplicationTestingBuilder.CreateAsync<Projects.MyApp_AppHost>();
        _app = await _appHost.BuildAsync();
        await _app.StartAsync();
    }

    [ClassCleanup]
    public static async Task ClassCleanup()
    {
        if (_app is not null)
        {
            await _app.DisposeAsync();
        }
    }

    [TestMethod]
    public async Task Chat_RespondsRelevantly()
    {
        var chatClient = _app.Services.GetRequiredService<IChatClient>();

        var response = await chatClient.GetResponseAsync("What is .NET Aspire?");

        Assert.IsNotNull(response);
        Assert.IsTrue(response.Text.Length > 0, "Response should not be empty.");
    }

    [TestMethod]
    public async Task Chat_ResponseQuality_IsCoherent()
    {
        var chatClient = _app.Services.GetRequiredService<IChatClient>();

        var response = await chatClient.GetResponseAsync("Explain dependency injection in one paragraph.");

        var evaluator = new CoherenceEvaluator();
        var result = await evaluator.EvaluateAsync(
            [new ChatMessage(ChatRole.User, "Explain dependency injection in one paragraph.")],
            new ChatResponse([new ChatMessage(ChatRole.Assistant, response.Text)]),
            chatClient);

        Assert.IsTrue(
            result.First().Value.Rating >= EvaluationRating.Good,
            $"Coherence rating was below threshold: {result.First().Value.Rating}");
    }

    [TestMethod]
    public async Task Chat_ResponseQuality_IsRelevant()
    {
        var chatClient = _app.Services.GetRequiredService<IChatClient>();

        var question = "What are the benefits of using .NET Aspire for cloud-native apps?";
        var response = await chatClient.GetResponseAsync(question);

        var evaluator = new RelevanceEvaluator();
        var result = await evaluator.EvaluateAsync(
            [new ChatMessage(ChatRole.User, question)],
            new ChatResponse([new ChatMessage(ChatRole.Assistant, response.Text)]),
            chatClient);

        Assert.IsTrue(
            result.First().Value.Rating >= EvaluationRating.Good,
            $"Relevance rating was below threshold: {result.First().Value.Rating}");
    }
}

